let S={progress:{},entries:[]},V=location.hash.slice(1)||'home';
async function api(u,b){let r=await fetch(u,b&&{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),d=await r.json();if(!r.ok)throw Error(d.error);return d}
const esc=x=>String(x??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
function shell(c){let links=[['home','Today'],['curriculum','Learning path'],['journal','Study journal'],['roadmap','Degree map'],['sources','Source library']];return `<aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark">f.</span> fieldnotes</a><div class="workspace-label">MICHAEL’S STUDY WORKSPACE</div><nav>${links.map(x=>`<a class="${V==x[0]?'active':''}" href="#${x[0]}">${x[1]}</a>`).join('')}</nav><div class="sidebar-foot">Computing & Artificial Intelligence<br><strong>Oxford Brookes · 2026–27</strong><span class="save-label">Saved locally on your Mac</span></div></aside><main><header><span>YOUR NEXT CHAPTER</span><span class="quiet">PCC · Second edition / 2 hours a day</span></header>${c}</main>`}
function home(){let n=Object.values(S.progress).filter(x=>x.status==='solid').length;return shell(`<section class="page-heading"><div><p class="eyebrow">YOUR STUDY WORKSPACE</p><h1>Build on what you know.</h1><p class="subtitle">Fast Python recall, then a clear bridge into your degree.</p></div><a class="button" href="#diagnostic">Start diagnostic ↗</a></section><div class="dashboard-grid"><section class="panel focus"><p class="eyebrow">START HERE · 45 MINUTES</p><h2>Recover your working memory.</h2><p>Write from a blank file. Mark what you can do independently. Spend revision time on evidence, not rereading.</p><div class="path-preview"><span>01 Recall</span><span>02 Practise</span><span>03 Prove</span></div><a class="text-link" href="#curriculum">Open the learning path →</a></section><section class="panel dark"><p class="eyebrow">PROGRESS</p><div class="big-number">${n}<small> / ${COURSE.tracks.length} solid</small></div><p>15m recall · 75m writing/testing · 20m preview · 10m log</p></section></div><section class="section"><div class="section-title"><h2>Five-pass sprint</h2></div><div class="track-grid">${['PCC 1–2 · syntax','PCC 3–5 · control flow','PCC 6–8 · functions/data','PCC 9–11 · OOP/files/tests','Degree bridge · Tkinter/data/Java'].map((x,i)=>`<article class="panel"><span class="track-number">0${i+1}</span><h3>${x}</h3><p>Read only the reference section, then write a small program without notes.</p></article>`).join('')}</div></section>`)}
function curriculum(){return shell(`<section class="page-heading"><div><p class="eyebrow">LEARNING PATH</p><h1>Study by proof.</h1><p class="subtitle">Each topic has drills, a transfer question, and saved evidence.</p></div></section><div class="lesson-list">${COURSE.tracks.map((x,i)=>{let p=S.progress[x.id]||{status:'new'};return `<article class="panel lesson"><div><span class="track-number">${String(i+1).padStart(2,'0')} · ${x.pcc}</span><h2>${x.title}</h2><p>${x.why}</p></div><div class="lesson-meta"><span class="status ${p.status}">${p.status}</span><a class="button small" href="#lesson-${x.id}">Open →</a></div></article>`}).join('')}</div>`)}
function lesson(id){let x=COURSE.tracks.find(y=>y.id===id),p=S.progress[id]||{status:'new',checks:[],notes:''};return shell(`<section class="page-heading"><div><p class="eyebrow">${x.pcc}</p><h1>${x.title}</h1><p class="subtitle">${x.why}</p></div><a class="button secondary" href="#curriculum">← All topics</a></section><section class="lesson-layout"><article class="panel"><h2>Drills</h2>${x.drills.map((d,i)=>`<label class="check"><input type="checkbox" data-c="${i}" ${p.checks?.includes(i)?'checked':''}> ${d}</label>`).join('')}<label class="field"><span>Evidence / error log</span><textarea id="notes" rows="6">${esc(p.notes)}</textarea></label><label class="field"><span>Status</span><select id="status"><option ${p.status==='new'?'selected':''}>new</option><option ${p.status==='learning'?'selected':''}>learning</option><option ${p.status==='solid'?'selected':''}>solid</option></select></label><button class="button" id="save">Save evidence</button></article><aside class="panel callout"><p class="eyebrow">TRANSFER QUESTION</p><h3>${x.q}</h3><p>Answer in your own words, then test it with code or a diagram.</p></aside></section>`)}
function journal(){return shell(`<section class="page-heading"><div><p class="eyebrow">STUDY JOURNAL</p><h1>Make the work visible.</h1><p class="subtitle">Sessions, errors and questions persist in SQLite.</p></div></section><section class="journal-layout"><form class="panel" id="jf"><label class="field"><span>Type</span><select name="type"><option>study</option><option>error</option><option>question</option><option>reflection</option><option>task</option></select></label><label class="field"><span>Topic</span><input name="topic"></label><label class="field"><span>Minutes</span><input name="minutes" type="number" value="120" min="0" max="1440"></label><label class="field"><span>Note</span><textarea name="text" rows="7" required></textarea></label><button class="button">Save entry</button></form><div class="entries">${S.entries.slice().reverse().map(e=>`<article class="panel entry"><span class="eyebrow">${e.date} · ${e.type} · ${e.minutes} min</span><h3>${esc(e.topic||'Study session')}</h3><p>${esc(e.text)}</p></article>`).join('')||'<article class="panel"><p class="quiet">Your first entry can be a diagnostic reflection.</p></article>'}</div></section>`)}
function simple(kind,title,sub,items){return shell(`<section class="page-heading"><div><p class="eyebrow">${kind.toUpperCase()}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div></section><div class="track-grid">${items.map(x=>`<article class="panel"><span class="track-number">${x[0]}</span><h2>${x[1]}</h2><p>${x[2]}</p></article>`).join('')}</div>`)}
function render(){let c=V==='home'?home():V==='curriculum'?curriculum():V==='journal'?journal():V==='roadmap'?simple('Degree map','Prepare for what follows.','Current guides drive now; later modules are preparation targets.',COURSE.degree):V==='sources'?simple('Source library','Current evidence first.','Historical files are enrichment, never current requirements.',COURSE.sources):V==='diagnostic'?simple('Diagnostic','Score your independence.','0 stuck · 1 with notes · 2 independently.',COURSE.tracks.slice(0,4).map(x=>[x.pcc,x.title,x.q])):V.startsWith('lesson-')?lesson(V.slice(7)):home();document.querySelector('#app').innerHTML=c;bind()}
function bind(){document.querySelector('#save')?.addEventListener('click',async()=>{let id=V.slice(7),p={status:document.querySelector('#status').value,notes:document.querySelector('#notes').value,checks:[...document.querySelectorAll('[data-c]:checked')].map(x=>+x.dataset.c)};await api('/api/save',{kind:'progress',id,record:p});S.progress[id]=p;alert('Evidence saved locally.')});document.querySelector('#jf')?.addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(e.target),r={type:f.get('type'),topic:f.get('topic'),minutes:+f.get('minutes'),text:f.get('text'),date:new Date().toISOString().slice(0,10)},d=await api('/api/save',{kind:'entry',record:r});S.entries.push({...r,id:d.id});render()})}addEventListener('hashchange',()=>{V=location.hash.slice(1)||'home';render()});(async()=>{try{S=await api('/api/state');render()}catch(e){document.querySelector('#app').innerHTML='<p class="loading">Could not open saved work. Start the portal at http://127.0.0.1:8765/.</p>'}})();
(function(){const oldRender=render;function coursePage(){return shell(`<section class="page-heading"><div><p class="eyebrow">UNIVERSITY COVERAGE</p><h1>What you need to learn.</h1><p class="subtitle">This is the Oxford Brookes course sequence. Open a Python cross-reference only when it supports the current outcome.</p></div></section><div class="track-grid">${COURSE.courses.map(c=>`<article class="panel"><span class="track-number">${c.code} · ${c.term}</span><h2>${c.name}</h2><p><b>Teaching sequence:</b> ${c.weeks}</p><p><b>Assessment:</b> ${c.assessment}</p></article>`).join('')}</div><section class="section"><div class="section-title"><h2>Outcome cross-reference</h2><span class="quiet">Python is attached to the degree map</span></div>${COURSE.tracks.map(x=>`<article class="panel lesson"><div><span class="track-number">${x.pcc}</span><h2>${x.title}</h2><p>${x.why}</p></div><a class="button small" href="#lesson-${x.id}">Evidence →</a></article>`).join('')}</section>`)}function renderCourse(){let c=V==='curriculum'?coursePage():V==='home'?home():V==='journal'?journal():V==='roadmap'?simple('Degree map','Prepare for what follows.','Current guides drive now; later modules are preparation targets.',COURSE.degree):V==='sources'?simple('Source library','Current evidence first.','Historical files are enrichment, never current requirements.',COURSE.sources):V==='diagnostic'?simple('Diagnostic','Score your independence.','0 stuck · 1 with notes · 2 independently.',COURSE.tracks.slice(0,4).map(x=>[x.pcc,x.title,x.q])):V.startsWith('lesson-')?lesson(V.slice(7)):home();document.querySelector('#app').innerHTML=c;bind()}render=renderCourse;render()})();
